-- ERP-COMERCIAL-360 A1: aditiva; nao executar na VPS sem gate proprio.
CREATE TABLE IF NOT EXISTS orcamentos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), group_id UUID NOT NULL REFERENCES groups(id), empresa_id UUID NOT NULL REFERENCES empresas(id), numero VARCHAR(8) NOT NULL, status TEXT NOT NULL DEFAULT 'EM_ABERTO' CHECK(status IN ('EM_ABERTO','CANCELADO')), cliente_empresa_id UUID NOT NULL REFERENCES cliente_empresas(id), condicao_pagamento_id UUID NOT NULL REFERENCES condicoes_pagamento(id), validade_em TIMESTAMPTZ NOT NULL, observacoes TEXT, subtotal NUMERIC(18,6) NOT NULL CHECK(subtotal>=0), desconto NUMERIC(18,6) NOT NULL DEFAULT 0 CHECK(desconto>=0), total NUMERIC(18,6) NOT NULL CHECK(total>=0), ativo BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc',now()), updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc',now()), UNIQUE(empresa_id,numero));
CREATE TABLE IF NOT EXISTS orcamento_itens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), group_id UUID NOT NULL REFERENCES groups(id), empresa_id UUID NOT NULL REFERENCES empresas(id), orcamento_id UUID NOT NULL REFERENCES orcamentos(id), produto_id UUID NOT NULL REFERENCES produtos(id), unidade_id UUID NOT NULL REFERENCES unidades_medida(id), descricao_snapshot TEXT NOT NULL, unidade_snapshot TEXT NOT NULL, quantidade NUMERIC(18,6) NOT NULL CHECK(quantidade>0), preco_unitario NUMERIC(18,6) NOT NULL CHECK(preco_unitario>=0), desconto NUMERIC(18,6) NOT NULL DEFAULT 0 CHECK(desconto>=0), subtotal NUMERIC(18,6) NOT NULL, total NUMERIC(18,6) NOT NULL, ativo BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc',now()), updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc',now()));
CREATE INDEX IF NOT EXISTS idx_orcamentos_scope ON orcamentos(group_id,empresa_id,status,created_at DESC); CREATE INDEX IF NOT EXISTS idx_orcamento_itens_scope ON orcamento_itens(group_id,empresa_id,orcamento_id); ALTER TABLE orcamentos ENABLE ROW LEVEL SECURITY; ALTER TABLE orcamentos FORCE ROW LEVEL SECURITY; ALTER TABLE orcamento_itens ENABLE ROW LEVEL SECURITY; ALTER TABLE orcamento_itens FORCE ROW LEVEL SECURITY;
-- Rollback documentado: DROP TABLE orcamento_itens; DROP TABLE orcamentos; somente com backup e gate.
